package com.notebysebas.sketch3d

import android.Manifest
import android.content.pm.PackageManager
import android.os.Build
import android.os.Bundle
import android.webkit.WebView
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat

/**
 * Host activity for the Sketch3D web app.
 *
 * `WryActivity` (generated by wry's build.rs into this same package) owns the
 * WebView; we only add the native export bridge on top of it.
 */
class MainActivity : WryActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        requestLegacyStoragePermission()
    }

    /**
     * Called by wry right after the WebView is created and before the page
     * starts loading, so the JS interface is available on the first script run.
     */
    override fun onWebViewCreate(webView: WebView) {
        super.onWebViewCreate(webView)

        webView.settings.domStorageEnabled = true
        webView.settings.databaseEnabled = true
        webView.settings.allowFileAccess = false
        webView.settings.allowContentAccess = false

        // window.AndroidBridge — used by index.html to write exported
        // GLB / OBJ / USDA / USDZ / PNG / JSON files to the device.
        webView.addJavascriptInterface(Exporter(this), "AndroidBridge")
    }

    /** Android 9 and older need the legacy write permission for Downloads/. */
    private fun requestLegacyStoragePermission() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) return
        val granted = ContextCompat.checkSelfPermission(
            this,
            Manifest.permission.WRITE_EXTERNAL_STORAGE
        ) == PackageManager.PERMISSION_GRANTED
        if (!granted) {
            ActivityCompat.requestPermissions(
                this,
                arrayOf(Manifest.permission.WRITE_EXTERNAL_STORAGE),
                1001
            )
        }
    }
}
